return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'bg_BG','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-08T20:37:32+00:00','po-revision-date'=>'2026-09-08T20:37:32+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'Пълен двигател за кеширане и оптимизация за WordPress: кеш на цяла страница, обектен кеш, почистване на база данни и CSS/JS оптимизация. Инсталирайте това, когато вашият хост не предоставя собствен кеш слой — на хостинг от Zinn Digital® инсталирайте Zinn® Cache вместо това. Кеширането на цяла страница изисква сървър LiteSpeed или OpenLiteSpeed с модула LSCache. GPLv3 форк на плъгина LiteSpeed Cache.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d часа','%d hour'=>'%d час','%d minutes'=>'%d минути','%d minute'=>'%d минута','Purged All!'=>'Всичко е изчистено!','Purged the blog!'=>'Блогът е изчистен!','Purged the URL!'=>'URL-ът е изчистен!','Purged!'=>'Изчистено!','Failed to upgrade.'=>'Неуспешно надграждане.','Upgraded successfully.'=>'Успешно надградено.','Dashboard'=>'Табло','OptimaX'=>'OptimaX','Presets'=>'Предварителни настройки','General'=>'Общи','Cache'=>'Кеш','CDN'=>'CDN','Image Optimization'=>'Оптимизация на изображения','Page Optimization'=>'Оптимизация на страницата','Database'=>'База данни','Crawler'=>'Обходчик','Toolbox'=>'Ин